#!/usr/bin/env node
// Embed the canonical guides for compiled binaries and the npm CLI alike.
import { readFileSync, writeFileSync } from "node:fs"
import { fileURLToPath } from "node:url"
const root = new URL("../", import.meta.url)
const ids = ["tx-plan", "tx-tasks", "tx-docs", "verify-invariants"]
const content = Object.fromEntries(ids.map(id => [id, readFileSync(new URL(`apps/cli/src/templates/shared-skills/${id}/SKILL.md`, root), "utf8")]))
writeFileSync(fileURLToPath(new URL("apps/cli/src/skills/embedded.ts", root)), `// Generated by scripts/bundle-skills.js. Edit templates/shared-skills instead.\nexport const embeddedSkills: Readonly<Record<string, string>> = ${JSON.stringify(content, null, 2)}\n`)
